import*as THREE from'three';export{THREE};export{materials}from'../../core/index.js';export{mesh,slab,portQuaternion,FACE}from'../../modeling/parts.js';import{mesh}from'../../modeling/parts.js';export const tau=Math.PI*2;
export function solid(parent,shape,depth,at,material,name){return mesh(parent,new THREE.ExtrudeGeometry(shape,{depth,bevelEnabled:false,curveSegments:40}),material,at,name);}
export function hole(s,x,y,r){const h=new THREE.Path();h.absarc(x,y,r,0,tau,false);s.holes.push(h);}
export function ring(parent,outer,inner,depth,at,material,name){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);hole(s,0,0,inner);return solid(parent,s,depth,at,material,name);}
export function ringY(parent,outer,inner,length,y,material,name){const s=new THREE.Shape();s.absarc(0,0,outer,0,tau,false);hole(s,0,0,inner);return mesh(parent,new THREE.ExtrudeGeometry(s,{depth:length,bevelEnabled:false,curveSegments:48}).rotateX(-Math.PI/2),material,[0,y,0],name);}
export function cappedSweep(curve,radius,segments=40,sides=10){const tube=new THREE.TubeGeometry(curve,segments,radius,sides,false),values=Array.from(tube.attributes.position.array),indices=Array.from(tube.index.array);for(const end of[0,1]){const c=curve.getPoint(end),center=values.length/3;values.push(c.x,c.y,c.z);const offset=end*segments*(sides+1),desired=curve.getTangent(end).multiplyScalar(end?1:-1);for(let i=0;i<sides;i++){const a=offset+i,b=offset+i+1,va=new THREE.Vector3().fromArray(values,a*3),vb=new THREE.Vector3().fromArray(values,b*3);if(va.sub(c).cross(vb.sub(c)).dot(desired)>0)indices.push(center,a,b);else indices.push(center,b,a);}}const g=new THREE.BufferGeometry().setAttribute('position',new THREE.Float32BufferAttribute(values,3));g.setIndex(indices);g.computeVertexNormals();tube.dispose();return g;}
